                int link = in.nextInt();
                int cd = in.nextInt();
                if (owner == 0) {
                    myDrones.add(new int[]{id, x, y, link, cd});
                }
            }

            // Wood 2 Boss: sends Drone 0 toward closest pulsar, Drone 1 as relay midpoint
